// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHeicDecoder {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHeicDecoder = UniffiVTableCallbackInterfaceHeicDecoder(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHeicDecoder.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HeicDecoder: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHeicDecoder.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HeicDecoder: handle missing in uniffiClone")
            }
        },
        decode: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> HeicPixels in
                guard let uniffiObj = try? FfiConverterTypeHeicDecoder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.decode(
                     path: try FfiConverterString.lift(path)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeHeicPixels_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeHeicDecodeError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceHeicDecoder> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceHeicDecoder>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitHeicDecoder() {
    uniffi_gallery_ffi_fn_init_callback_vtable_heicdecoder(UniffiCallbackInterfaceHeicDecoder.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHeicDecoder: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<HeicDecoder>()

    typealias FfiType = UInt64
    typealias SwiftType = HeicDecoder

    public static func lift(_ handle: UInt64) throws -> HeicDecoder {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return HeicDecoderImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: HeicDecoder) -> UInt64 {
         if let rustImpl = value as? HeicDecoderImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HeicDecoder {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: HeicDecoder, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


