/**
 * Why a scanner call failed.
 *
 * A scan itself is close to infallible — an unreadable directory is *data*
 * (`failed_directory_paths`), not an error, because treating it as one is how
 * a transient listing failure wipes a subtree. What is left is the two things
 * that genuinely cannot produce an answer.
 */
public 
enum ScanError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * [`ScannerSession::cancel`] was called before the walk finished. No
     * partial outcome is returned: half a tree looks exactly like a library
     * whose second half was deleted.
     */
    case Cancelled
    /**
     * A snapshot file could not be read or written.
     */
    case Io(
        /**
         * The path involved.
         */path: String, 
        /**
         * Platform message; for logs only.
         */detail: String
    )
    /**
     * The snapshot is not JSON, or carries no `version`.
     */
    case SnapshotCorrupt(
        /**
         * Parser message; for logs only.
         */detail: String
    )
    /**
     * The snapshot's `version` is not the one this build writes. The caller
     * evicts, exactly as `JSONDiskCache` does.
     */
    case SnapshotVersionMismatch(
        /**
         * What the file claims.
         */found: Int64, 
        /**
         * What this build writes.
         */expected: Int64
    )
    /**
     * The version matched and the payload still did not decode.
     */
    case SnapshotPayload(
        /**
         * Parser message; for logs only.
         */detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ScanError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeScanError: FfiConverterRustBuffer {
    typealias SwiftType = ScanError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ScanError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Cancelled
        case 2: return .Io(
            path: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .SnapshotCorrupt(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .SnapshotVersionMismatch(
            found: try FfiConverterInt64.read(from: &buf), 
            expected: try FfiConverterInt64.read(from: &buf)
            )
        case 5: return .SnapshotPayload(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ScanError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Cancelled:
            writeInt(&buf, Int32(1))
        
        
        case let .Io(path,detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .SnapshotCorrupt(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .SnapshotVersionMismatch(found,expected):
            writeInt(&buf, Int32(4))
            FfiConverterInt64.write(found, into: &buf)
            FfiConverterInt64.write(expected, into: &buf)
            
        
        case let .SnapshotPayload(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


