/**
 * Why a tagging call failed.
 *
 * A flattening of [`MlError`] (plus the one failure mode only this layer has,
 * [`TaggingError::AlreadyRunning`]). The `detail` strings are for logs — the
 * *variant* is what callers switch on.
 */
public 
enum TaggingError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A file named by the model-pack manifest is missing.
     */
    case PackFileMissing(
        /**
         * Path that was expected to exist.
         */path: String
    )
    /**
     * A model-pack file does not hash to what the manifest claims.
     */
    case PackHashMismatch(
        /**
         * Manifest-relative file name.
         */file: String, 
        /**
         * Hex SHA-256 from the manifest.
         */expected: String, 
        /**
         * Hex SHA-256 actually computed.
         */actual: String
    )
    /**
     * The manifest or the label set is malformed.
     */
    case PackInvalid(
        /**
         * What was wrong; for logs only.
         */detail: String
    )
    /**
     * The cache DB is unusable.
     */
    case Cache(
        /**
         * SQLite message; for logs only.
         */detail: String
    )
    /**
     * The inference backend refused the model.
     */
    case Inference(
        /**
         * Backend message; for logs only.
         */detail: String
    )
    /**
     * A filesystem operation failed.
     */
    case Io(
        /**
         * The path involved.
         */path: String, 
        /**
         * Platform message; for logs only.
         */detail: String
    )
    /**
     * A sidecar could not be parsed or written.
     */
    case Sidecar(
        /**
         * Parser/writer message; for logs only.
         */detail: String
    )
    /**
     * The run was cancelled.
     */
    case Cancelled
    /**
     * `start` was called while a run was already in flight.
     */
    case AlreadyRunning

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension TaggingError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTaggingError: FfiConverterRustBuffer {
    typealias SwiftType = TaggingError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TaggingError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .PackFileMissing(
            path: try FfiConverterString.read(from: &buf)
            )
        case 2: return .PackHashMismatch(
            file: try FfiConverterString.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf), 
            actual: try FfiConverterString.read(from: &buf)
            )
        case 3: return .PackInvalid(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Cache(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Inference(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Io(
            path: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Sidecar(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Cancelled
        case 9: return .AlreadyRunning

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TaggingError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .PackFileMissing(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .PackHashMismatch(file,expected,actual):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(file, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)
            
        
        case let .PackInvalid(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Cache(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Inference(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Io(path,detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Sidecar(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(8))
        
        
        case .AlreadyRunning:
            writeInt(&buf, Int32(9))
        
        }
    }
}


