        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pack
        
        case 2: return .cacheDb
        
        case 3: return .inference
        
        case 4: return .io
        
        case 5: return .sidecar
        
        case 6: return .cancelled
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TaggingFailure, into buf: inout [UInt8]) {
